fn handle_io<T>(res: io::Result<T>) -> T {
    match res {
        Ok(status) => status,
        Err(err) => panic!("Error: {}", err),
    }
}

fn find_git_root() -> io::Result<PathBuf> {
    while !PathBuf::from(".git").exists() {
        if std::env::set_current_dir("..").is_err() {
            return Err(io::Error::new(
                io::ErrorKind::NotFound,
                "Git root not found",
            ));
        }
    }

    std::env::current_dir()
}

